from __future__ import annotations

import base64
import io
import json
import sys
import zipfile
from pathlib import Path

BUNDLE = """"""


def validate_notebook(path: Path) -> None:
    data = json.loads(path.read_text(encoding="utf-8"))
    if data.get("nbformat") != 4:
        raise ValueError(f"Invalid notebook format: {path}")
    if not isinstance(data.get("cells"), list) or not data["cells"]:
        raise ValueError(f"Notebook has no cells: {path}")


def main() -> int:
    if len(sys.argv) != 2:
        print("Usage: python install_lesson_bundle.py <destination>")
        return 2

    destination = Path(sys.argv[1]).resolve()
    destination.mkdir(parents=True, exist_ok=True)

    payload = base64.b64decode(BUNDLE)
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        archive.extractall(destination)

    notebooks = sorted(destination.glob("*.ipynb"))
    for notebook in notebooks:
        validate_notebook(notebook)

    print(f"Lesson notebooks installed: {len(notebooks)}")
    print(f"Destination: {destination}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
